        modelBuilder.Entity<AcadAsistencias>(entity =>
        {
            entity.HasKey(e => e.IdAsistencia).HasName("PRIMARY");

            entity
                .ToTable("acad_asistencias", tb => tb.HasComment("Asistencia por estudiante y sesion"))
                .HasCharSet("utf8mb4")
                .UseCollation("utf8mb4_unicode_ci");

            entity.HasIndex(e => new { e.IdMatricula, e.Estado }, "ix_acad_asistencias_matricula_estado");

            entity.HasIndex(e => new { e.IdSesion, e.IdMatricula }, "uq_acad_asistencias_sesion_matricula").IsUnique();

            entity.Property(e => e.IdAsistencia)
                .HasColumnType("int(11)")
                .HasColumnName("idAsistencia");
            entity.Property(e => e.Estado)
                .IsRequired()
                .HasDefaultValueSql("'presente'")
                .HasColumnType("enum('presente','ausente','atraso','justificado')")
                .HasColumnName("estado");
            entity.Property(e => e.FechaActualizacion)
                .ValueGeneratedOnAddOrUpdate()
                .HasColumnType("datetime")
                .HasColumnName("fechaActualizacion");
            entity.Property(e => e.FechaCreacion)
                .HasDefaultValueSql("CURRENT_TIMESTAMP")
                .HasColumnType("datetime")
                .HasColumnName("fechaCreacion");
            entity.Property(e => e.IdMatricula)
                .HasComment("FK matriculas.idMatricula")
                .HasColumnType("int(11)")
                .HasColumnName("idMatricula");
            entity.Property(e => e.IdSesion)
                .HasComment("FK acad_sesiones.idSesion")
                .HasColumnType("int(11)")
                .HasColumnName("idSesion");
            entity.Property(e => e.MinutosAtraso)
                .HasComment("Solo aplica cuando estado = atraso")
                .HasColumnType("smallint(5) unsigned")
                .HasColumnName("minutosAtraso");
            entity.Property(e => e.Observacion)
                .HasMaxLength(200)
                .HasColumnName("observacion");
            entity.Property(e => e.UsuarioActualiza)
                .HasMaxLength(25)
                .HasColumnName("usuarioActualiza");
            entity.Property(e => e.UsuarioCreacion)
                .IsRequired()
                .HasMaxLength(25)
                .HasComment("usuarios.idSigafi del autor")
                .HasColumnName("usuarioCreacion");

            entity.HasOne(d => d.IdMatriculaNavigation).WithMany(p => p.AcadAsistencias)
                .HasForeignKey(d => d.IdMatricula)
                .OnDelete(DeleteBehavior.ClientSetNull)
                .HasConstraintName("fk_acad_asistencias_matricula");

            entity.HasOne(d => d.IdSesionNavigation).WithMany(p => p.AcadAsistencias)
                .HasForeignKey(d => d.IdSesion)
                .HasConstraintName("fk_acad_asistencias_sesion");
        });

