        modelBuilder.Entity<AcadSesiones>(entity =>
        {
            entity.HasKey(e => e.IdSesion).HasName("PRIMARY");

            entity
                .ToTable("acad_sesiones", tb => tb.HasComment("Sesion de clase dictada (grano: grupo contiguo de bloques en un dia)"))
                .HasCharSet("utf8mb4")
                .UseCollation("utf8mb4_unicode_ci");

            entity.HasIndex(e => new { e.IdAsignacion, e.Activo }, "ix_acad_sesiones_asignacion");

            entity.HasIndex(e => new { e.Estado, e.IdFecha }, "ix_acad_sesiones_estado_fecha");

            entity.HasIndex(e => e.IdFecha, "ix_acad_sesiones_fecha");

            entity.HasIndex(e => new { e.IdAsignacion, e.IdFecha, e.NumeroBloque }, "uq_acad_sesiones_asignacion_fecha_bloque").IsUnique();

            entity.Property(e => e.IdSesion)
                .HasColumnType("int(11)")
                .HasColumnName("idSesion");
            entity.Property(e => e.Activo)
                .IsRequired()
                .HasDefaultValueSql("'1'")
                .HasColumnName("activo");
            entity.Property(e => e.Estado)
                .IsRequired()
                .HasDefaultValueSql("'borrador'")
                .HasComment("cerrada = lista tomada. Editable solo dentro de la ventana de correccion.")
                .HasColumnType("enum('borrador','cerrada')")
                .HasColumnName("estado");
            entity.Property(e => e.FechaActualizacion)
                .ValueGeneratedOnAddOrUpdate()
                .HasColumnType("datetime")
                .HasColumnName("fechaActualizacion");
            entity.Property(e => e.FechaCierre)
                .HasColumnType("datetime")
                .HasColumnName("fechaCierre");
            entity.Property(e => e.FechaCreacion)
                .HasDefaultValueSql("CURRENT_TIMESTAMP")
                .HasColumnType("datetime")
                .HasColumnName("fechaCreacion");
            entity.Property(e => e.IdAsignacion)
                .HasComment("FK asignaciones_profesores.idAsignacion (columna UNIQUE, no la PK compuesta)")
                .HasColumnType("int(11)")
                .HasColumnName("idAsignacion");
            entity.Property(e => e.IdFecha)
                .HasComment("FK fechas_horarios.idFecha — el dia de la clase")
                .HasColumnType("int(11)")
                .HasColumnName("idFecha");
            entity.Property(e => e.NumeroBloque)
                .HasDefaultValueSql("'1'")
                .HasComment("Ordinal del grupo contiguo de bloques dentro del dia. Normalmente 1.")
                .HasColumnType("tinyint(4)")
                .HasColumnName("numeroBloque");
            entity.Property(e => e.Observacion)
                .HasMaxLength(500)
                .HasComment("Observaciones generales de la sesion")
                .HasColumnName("observacion");
            entity.Property(e => e.Tema)
                .IsRequired()
                .HasMaxLength(250)
                .HasComment("Tema de la clase. Vacio mientras la sesion esta en borrador; requerido al cerrar.")
                .HasColumnName("tema");
            entity.Property(e => e.UsuarioActualiza)
                .HasMaxLength(25)
                .HasColumnName("usuarioActualiza");
            entity.Property(e => e.UsuarioCreacion)
                .IsRequired()
                .HasMaxLength(25)
                .HasComment("usuarios.idSigafi del docente")
                .HasColumnName("usuarioCreacion");

            entity.HasOne(d => d.IdAsignacionNavigation).WithMany(p => p.AcadSesiones)
                .HasPrincipalKey(p => p.IdAsignacion)
                .HasForeignKey(d => d.IdAsignacion)
                .OnDelete(DeleteBehavior.ClientSetNull)
                .HasConstraintName("fk_acad_sesiones_asignacion");

            entity.HasOne(d => d.IdFechaNavigation).WithMany(p => p.AcadSesiones)
                .HasForeignKey(d => d.IdFecha)
                .OnDelete(DeleteBehavior.ClientSetNull)
                .HasConstraintName("fk_acad_sesiones_fecha");
